# area: callables
# hypothesis: a generic function passed where a Callable takes another generic Callable must solve its type variable consistently across the nested parameter, so run(wrap, inc) reveals int and a mismatched argument to apply_twice is rejected.
from collections.abc import Callable
from typing import assert_type, reveal_type


def apply_twice[T](f: Callable[[T], T], x: T) -> T:
    return f(f(x))


def run[T](cb: Callable[[Callable[[T], T]], T], f: Callable[[T], T]) -> T:
    return cb(f)


def wrap(f: Callable[[int], int]) -> int:
    return f(3)


def inc(n: int) -> int:
    return n + 1


def ident[T](x: T) -> T:
    return x


reveal_type(apply_twice(inc, 1))
assert_type(apply_twice(inc, 1), int)
reveal_type(apply_twice(ident, 's'))
reveal_type(run(wrap, inc))
print(apply_twice(inc, 1), apply_twice(ident, 's'), run(wrap, inc))

try:
    apply_twice(inc, 'a')  # expect-error: T solved as int, got str
except TypeError as exc:
    print('runtime:', type(exc).__name__)
